#include <stdio.h>
#include <ctype.h>

#define MAX_WORD_SIZE 1024

void process_file_characters(FILE *file, char *word, size_t word_size) {
    int ch;
    int i = 0;
    int in_quote = 0;

    while ((ch = fgetc(file)) != EOF && i < (word_size - 1)) {
        if (ch == '\\') {
            // Handle escape sequence
            ch = fgetc(file);
            if (ch == 'n') {
                word[i++] = '\n';
            } else if (ch == 't') {
                word[i++] = '\t';
            } else if (isdigit(ch)) {
                // Handle octal escape
                int value = ch - '0';
                int count = 0;
                while (count < 2 && (ch = fgetc(file)) != EOF && isdigit(ch)) {
                    value = value * 8 + (ch - '0');
                    count++;
                }
                ungetc(ch, file); // Put back the non-digit character
                word[i++] = value;
            } else if (ch == 'x' || ch == 'X') {
                // Handle hex escape
                int value = 0;
                int read_hex = 0;
                while (read_hex < 2 && (ch = fgetc(file)) != EOF && isxdigit(ch)) {
                    value = value * 16 + (isalpha(ch) ? toupper(ch) - 'A' + 10 : ch - '0');
                    read_hex++;
                }
                ungetc(ch, file); // Put back the non-hex character
                word[i++] = value;
            } else {
                // Non-special escape character
                word[i++] = ch;
            }
        } else if (ch == '"') {
            // Toggle quote state
            in_quote = !in_quote;
            word[i++] = ch;
        } else if (isspace(ch) && !in_quote) {
            // Break on whitespace outside quotes
            break;
        } else if (ch == '#' && !in_quote) {
            // Break on comment character outside quotes
            break;
        } else {
            word[i++] = ch;
        }
    }
    word[i] = '\0'; // Null-terminate the word
}
